  Tt = `Valve Corporation`,
  Et = `關於講者`,
  Dt = `Gautam Babbar - Valve 設計師`,
  Ot = `在過去 15 年內，Gautam 曾參與了許多 Valve 系列作品與產品的相關工作，包括《惡靈勢力》、《傳送門》、《戰慄時空》、《絕對武力》、《Alien Swarm》 和 Steam。目前他主要的工作內容為 CS:GO。`,
  kt = `Adil Sardar - Valve 工程師`,
  At = `Adil 為 Steam 軟體開發團隊的一員。他為 Steam 的技術堆疊建立了許多功能。最近工作內容主要集中在活動、特賣及實況直播的技術支援。`,
  jt = `Alden Kroll - Valve 設計師`,
  Mt = `Alden Kroll 為 Valve 的設計師，已任職超過 15 年，參與的工作除了 Steam 還有遊戲，如《絕地要塞 2》、《傳送門》和《惡靈勢力》。Alden 目前為 Steam 商店和 Steamworks 開發工具擔任橫跨設計、業務與溝通等不同領域的設計師，同時也協助統整開發者外展和溝通。`,
  Nt = `Jenny Windom - Rose City Games 通訊處經理`,
  Pt = `Jenny 對獨立遊戲及其社群都充滿熱情，積極為他們爭取在產業內各層級的代表性。她的工作資歷包括在 Rose City Games 擔任通訊處經理（該公司發行了《The World Next Door》、《磁片騎士》及《Garden Story》）、在 Kowloon Nights 通訊處任職，以及以自由業身份擔任獨立遊戲鑑賞家和內容創作者！`,
  Ft = `Joe Tirado - System Era Softworks 行銷傳播部主管`,
  It = `Joe 是一名藝術家、設計師和多元化提倡者。在 System Era Softworks 任職時，Joe 曾為《Astroneer》開發團隊的一員，該遊戲於 2019 年獲得了 Webby Awards 的「Best Adventure Game」（最佳冒險遊戲）和 SXSW Gaming Awards 的「Gamer’s Voice Award」（玩家之聲獎）等大獎。他也是 Latinx in Gaming 的共同創辦人，該組織提供一個平台以連結並代表遊戲產業內的拉丁裔。`,
  Lt = `Steam 通訊工具使用示範`,
  Rt = `Alden Kroll 和 Adil Sardar - Valve Corporation`,
  zt = `上午 11:00 - 下午 12:02（PT）`,
  Bt = `Steam 活動和公告的幾位建立者會在此場次為各位逐步解說此功能。學習基本知識、看看工具的實際應用，並聽取最佳作法，以充分利用 Steam 通訊工具的功能。`,
  Vt = `讓更新說明一切`,
  Ht = `Gautam Babbar - Valve Corporation`,
  Ut = `上午 10:20 - 10:47（PT）`,
  Wt = `《絕對武力：全球攻勢》擁有龐大的全球玩家社群。Gautam 會在此演講中詳盡介紹 CS:GO 團隊如何使用內容和遊戲變更與如此廣大的玩家群溝通。他還會就遊戲團隊決定該何時發聲與何時聆聽這個問題分享一些看法。`,
  Gt = `與玩家交流：第 1 部分`,
  Kt = `Jenny Windom - Rose City Games`,
  qt = `下午 12:15 - 12:55（PT）`,
  Jt = `有時候，各位可能會覺得玩家的交流和活動似乎只適用於大型的多人線上遊戲。不過，Jenny 在這次談話中將證明事實並非如此。本場次將重點討論兩款較小型的單人遊戲用來建立社群和鼓勵參與之策略和技巧。兩款遊戲為：由 Picogram 開發，即將發行的的冒險角色扮演遊戲《Garden Story》，以及由 Rose City Games 開發的卡牌對戰遊戲《磁片騎士》。`,
  Yt = `與玩家交流：第 2 部分`,
  Xt = `Joe Tirado - System Era Softworks`,
  Zt = `下午 1:00 - 1:44（PT）`,
  Qt = `《Astroneer》於 2016 年底以 Steam 搶先體驗首度登場。接近 5 年後，這款遊戲持續在新舊玩家間引起共鳴。Joe 分享小型團隊如何透過溝通讓玩家在開發過程的初期一起參與，以及在遊戲的整個生命週期中如何處理意見回饋的經驗。`,
