  jn = `（建議，方便我們安排活動）`,
  Mn = `您的遊戲目前預定將出現於下列區塊中。您遊戲所在的分頁是由您在下方「遊戲類別」中所選的類別而定，而區塊則是由遊戲套用的商店標籤所決定。請查看活動預覽以了解您的遊戲最適合在哪些區塊出現（比方說，如果您的遊戲是點擊冒險遊戲，就要確定在下方選擇「冒險」類別，且遊戲的商店頁面標籤中包括「點擊冒險」）。請注意，這可能會因最終的整理變動而有所改變。`,
