  mM = `在您首次發行試玩版時，您可選擇讓 Steam 通知所有將您的完整版遊戲加入願望清單的使用者。此選項會在您推出試玩版後的頭兩週內發送通知，只可發送一次。願望清單通知不可在兩週內再次發送，因此若您計畫要在兩週內推出遊戲，則不適合採用此選項。`,
