  FN = `有些遊戲可以在不看螢幕的情況下遊玩。例如，遊戲可能完全依靠音訊來遊玩，或遊戲提供足夠的螢幕閱讀器或朗讀支援，能在沒有視覺的情況下獲得完整體驗。`,
  IN = `您的遊戲無需視覺也能遊玩嗎？`,
  LN = `是，玩家可以在完全不看螢幕的情況下遊玩。`,
  RN = `否，我的遊戲需要視覺才可遊玩。`,
  zN = `自訂音量控制`,
  BN = `遊戲內不同類型音訊的音量都可各自單獨調整。`,
  VN = `玩家可能需要將會干擾的聲音的音量降低，如此才能專注在他們需要聽到的聲音。如果您的遊戲可自訂音量控制，玩家就能調整不同類型聲音（如音樂、音效、環境音效和角色語音等）的相對音量。單一個音量控制條不符合這個標準。如需建議，請參閱<1>輔助功能的 Steamworks 文獻</1>。`,
  HN = `您的遊戲可自訂音量控制嗎？`,
